-- RODOS — 76 моделей у всіх поточних колекціях.
-- Фото та технічні характеристики уже додані попередніми пакетами.

update public.products
set description = case collection
  when 'Atlantic ПВХ' then name || ' — міжкімнатні двері RODOS Atlantic із практичним ПВХ-покриттям. Оберіть глухе, частково засклене або засклене полотно відповідно до моделі та вашого інтер’єру.'
  when 'Cortes фарба' then name || ' — пофарбовані міжкімнатні двері RODOS Cortes. Базове покриття — білий мат, також доступне фарбування у вибрані кольори палітри RAL; варіант полотна залежить від моделі.'
  when 'Loft фарба' then name || ' — пофарбовані міжкімнатні двері RODOS Loft у лаконічному сучасному стилі. Білий матовий базовий колір можна доповнити вибраними відтінками RAL; тип полотна залежить від моделі.'
  when 'Loft шпон' then name || ' — міжкімнатні двері RODOS Loft з натуральним шпоном. Виразна текстура дерева додає інтер’єру тепла, а точний декор і комплектацію допоможе підібрати менеджер.'
  when 'Royal шпон' then name || ' — міжкімнатні двері RODOS Royal із натуральним шпоном. Колекція поєднує класичні пропорції та природну текстуру дерева; варіант полотна залежить від моделі.'
  when 'Siena фарба' then name || ' — пофарбовані міжкімнатні двері RODOS Siena у класичному стилі. Дерев’яне полотно товщиною 44 мм доступне у стандартних розмірах 600–900 × 2000 мм та може виготовлятися індивідуально.'
  when 'Style ПВХ' then name || ' — міжкімнатні двері RODOS Style із ПВХ-покриттям. Практичне рішення для сучасного інтер’єру; точний варіант декору, скла й комплектації залежить від обраної моделі.'
  else description
end
where brand = 'Rodos';
